export const meta = {
  name: 'council',
  description: 'Opus, Sonnet, Codex Astra and Gemini Hydrogen solve one task independently, debate it on an evidence ledger, and converge on one result',
  whenToUse: 'Use when a task deserves several independent minds that must then agree: a subtle bug, a design with real trade-offs, an investigation where the obvious answer may be wrong. Unlike /ensemble, which ranks candidates for you to pick, the council debates in rounds and converges on one result, falling back to an evidence scorecard when it cannot agree. Expensive (roughly 30-50 agent turns). Before setup, a shaper and a fresh challenger clarify the goal (2 Opus turns); a groomed ticket from the dark-factory:groom skill or an absolute brief file path in brief gets one re-check instead; questions stop for the user; brief: false (--no-brief) skips it. Before any seat starts, two reviewers attack the acceptance criteria (coverage: Codex Astra, intent: Claude Opus) and the panel rules on what they find; questions only the user can settle are answered on the most conservative reading and reported as assumptions, or with spec: "ask" the run stops and asks; spec: false skips it. In implement mode, two auditors who never saw the debate then review the final version (correctness: Codex Astra, design: Claude Opus) and the author gets one fix pass; pass audit: false to skip it, or audit: {correctness: "sol", design: "sonnet"} to swap their models. Not for mechanical work. Seats work in git worktrees checked out from HEAD, so they cannot see uncommitted files: if the work follows a plan or any other document that is not committed (a plan from plan mode under ~/.claude/plans/, an untracked PLAN.md, a checklist), call it with object args and pass the document\'s absolute path in `plan`, e.g. {task: "Do item 13 on the bug checklist", plan: ["/abs/path/BUG_CHECK_LIST.md"]}. Say in the task which part to do; do not paste the document. The council snapshots it for every seat. The default lineup is opus, sonnet, astra, gemini; when the user asks for other models (say, because one vendor\'s quota is used up), pass them in `seats`, e.g. {task: "...", seats: ["opus", "sonnet", "astra", "sol"]}, or prefix a string task with --seats opus,sonnet,astra,sol.',
  phases: [
    { title: 'Brief', detail: 'shape the outcome and purpose, or re-check a groomed ticket or a supplied brief, before setup', model: 'opus' },
    { title: 'Setup', detail: 'worktrees, room, and acceptance criteria fixed before anyone starts', model: 'opus' },
    { title: 'Spec', detail: 'two reviewers attack the acceptance criteria before work begins; the panel rules; the criteria are amended and open questions settled as assumptions' },
    { title: 'Solve', detail: 'every seat works alone, blind; neutral checks' },
    { title: 'Round 1', detail: 'critique, challenge, adopt, revise, vote; neutral checks and adjudication' },
    { title: 'Round 2', detail: 'critique, challenge, adopt, revise, vote; neutral checks and adjudication' },
    { title: 'Round 3', detail: 'critique, challenge, adopt, revise, vote; neutral checks and adjudication' },
    { title: 'Synthesize', detail: 'the winning author folds in amendments and fixes standing findings' },
    { title: 'Ratify', detail: 'the other seats sign off or object; one fix pass for upheld objections' },
    { title: 'Audit', detail: 'auditors who never saw the debate review the final version, correctness and design; one fix pass for what is upheld' },
    { title: 'Retro', detail: 'one agent reviews the process notes and suggests changes to the workflow', model: 'sonnet' },
  ],
}

// GENERATED by tools/build.mjs from the files under src/: edit those, then `make build` (install.sh does).

// council — several models from up to three vendors (Claude, Codex, Gemini) solve one task
// independently, debate it on an evidence ledger, and converge on one result.
//
//   /council <task>
//   args: {task, plan, mode, seats, rounds, effort, context, criteria, verify, repo, consensusAt, escalateAt,
//          panel, checkModel, allowDirty, clarifications, narrow, retro, timeoutMin, ballot, approval, spec, audit}
//   plan:   path(s) of a plan or other document the work follows. Worktrees check out HEAD, so an
//           uncommitted plan is invisible to seats; `council init --ref` snapshots it into the run.
//   seats:  default ['opus', 'sonnet', 'astra', 'gemini']; also 'sol', 'luna', 'terra', 'argon', 'neon', 'fable', 'haiku',
//           'codex:<slug>', 'gemini:<slug>'. A list, or a comma-separated string. A string task may
//           start with `--seats opus,sonnet,astra,sol` instead.
//   effort: 'high' (default) for every seat, or {astra: 'xhigh', ...}
//   mode:   'implement' | 'investigate' | 'design'; auto-detected from the task
//   narrow: true (default): after each debate round, weak positions with no support leave contention
//   retro:  true (default, while the workflow is being tuned): every agent may note what in its turn got
//           in the way, and one agent turns the notes into suggested changes to the workflow at the end
//   timeoutMin: deadline for a Codex or Gemini turn, minutes; a number or {spec, solve, debate, final, ratify, panel, ballot, audit}
//   spec:   true (default): before any seat starts, reviewers look for what the acceptance criteria miss
//           (coverage: 'astra') or leave open (intent: 'opus'), the panel rules, and the criteria are amended.
//           Questions only the user can settle become assumptions; 'ask' stops for the user instead;
//           {coverage, intent, effort, ask} swaps models; false skips it
//   audit:  true (default; implement mode only): after ratification, auditors who never saw the debate review the
//           final version, correctness ('astra') and design ('opus'); {correctness, design, effort} swaps them; false skips it
//   ballot:   false (default). Experiment: re-vote after a round's checks when one vote short of consensus
//   approval: false (default). Experiment: seats also list acceptable positions, counted when strict votes don't converge
//
// Shape: Setup -> Spec review (-> panel -> amend) -> Solve (blind) -> checks -> [Round k: posts -> checks + panel -> stop rule -> narrow]* ->
// Synthesize -> Ratify (-> one fix pass) -> Audit (-> one fix pass -> re-review of the fix). Claude seats are workflow agents; Codex and Gemini seats
// are reached through a Haiku relay that runs `council seat-run`, which resumes the seat's own
// Codex thread or Gemini (agy) conversation, so they keep their memory across rounds. All shell
// work lives in bin/dark-factory.
//
// The workflow is the moderator: it keeps turn order, the ledger, and the stop rule. It never
// judges. Neutral checkers and a two-vendor panel rule on claims; this script computes every
// score from those rulings.
//
// Context is kept focused: prompts point at files instead of pasting them, the ledger digest is
// capped, from round 2 seats read what changed since they last looked rather than everything
// again, the field narrows to the positions still in contention, and Claude seats (fresh agents
// each turn) carry private notes forward where Codex and Gemini seats keep their thread.
